// A supported DNS provider.
// Ref: #/components/schemas/Provider
type Provider string

const (
	ProviderCloudflare   Provider = "cloudflare"
	ProviderTencentcloud Provider = "tencentcloud"
	ProviderAlidns       Provider = "alidns"
	ProviderRoute53      Provider = "route53"
)

// AllValues returns all Provider values.
func (Provider) AllValues() []Provider {
	return []Provider{
		ProviderCloudflare,
		ProviderTencentcloud,
		ProviderAlidns,
		ProviderRoute53,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Provider) MarshalText() ([]byte, error) {
	switch s {
	case ProviderCloudflare:
		return []byte(s), nil
	case ProviderTencentcloud:
		return []byte(s), nil
	case ProviderAlidns:
		return []byte(s), nil
	case ProviderRoute53:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Provider) UnmarshalText(data []byte) error {
	switch Provider(data) {
	case ProviderCloudflare:
		*s = ProviderCloudflare
		return nil
	case ProviderTencentcloud:
		*s = ProviderTencentcloud
		return nil
	case ProviderAlidns:
		*s = ProviderAlidns
		return nil
	case ProviderRoute53:
		*s = ProviderRoute53
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

// Every record sharing a name and a type.
// Ref: #/components/schemas/RecordSetResource
type RecordSetResource struct {
	// The name relative to the domain. `@` denotes the domain itself.
	Name string `json:"name"`
	// Time to live, in seconds. 0 leaves the choice to the provider.
	TTL  int64      `json:"ttl"`
	Type RecordType `json:"type"`
	// Every value in this record set, in unescaped zone-file RDATA syntax:
	//
	//  - `A`, `AAAA`: `192.0.2.1`, `2001:db8::1`
	//  - `CNAME`, `NS`: `target.example.com.`, absolute, with a trailing dot
	//  - `TXT`: the text itself, neither quoted nor escaped
	//  - `MX`: `10 mail.example.com.`
	//  - `SRV`: `10 20 443 target.example.com.`
	//  - `CAA`: `0 issue "letsencrypt.org"`
	Values []string `json:"values"`
	// The domain in absolute form, with a trailing dot.
	Zone string `json:"zone"`
}

// GetName returns the value of Name.
func (s *RecordSetResource) GetName() string {
	return s.Name
}

// GetTTL returns the value of TTL.
func (s *RecordSetResource) GetTTL() int64 {
	return s.TTL
}

// GetType returns the value of Type.
func (s *RecordSetResource) GetType() RecordType {
	return s.Type
}

// GetValues returns the value of Values.
func (s *RecordSetResource) GetValues() []string {
	return s.Values
}

// GetZone returns the value of Zone.
func (s *RecordSetResource) GetZone() string {
	return s.Zone
}

// SetName sets the value of Name.
func (s *RecordSetResource) SetName(val string) {
	s.Name = val
}

// SetTTL sets the value of TTL.
func (s *RecordSetResource) SetTTL(val int64) {
	s.TTL = val
}

